package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import java.io.*; import java.nio.file.*; import java.util.zip.*;
public final class LogArchiveService { private final AgentProperties p;public LogArchiveService(AgentProperties p){this.p=p;} public Path collect(String id)throws IOException{var s=p.getServices().values().stream().filter(x->id.equals(x.getServiceId())).findFirst().orElseThrow(()->new SecurityException("unknown service"));Path configured=Path.of(s.getLogRoot()).toAbsolutePath().normalize();if(Files.isSymbolicLink(configured)||!Files.isDirectory(configured,LinkOption.NOFOLLOW_LINKS))throw new FileNotFoundException("log root");Path root=configured.toRealPath(LinkOption.NOFOLLOW_LINKS);Path work=Path.of(s.getInstallRoot()).toAbsolutePath().normalize().resolve("work");Files.createDirectories(work);Path zip=Files.createTempFile(work,"logs-"+id+"-",".zip");long[] total={0};try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(zip));var walk=Files.walk(root)){walk.filter(x->!Files.isSymbolicLink(x)).filter(x->Files.isRegularFile(x,LinkOption.NOFOLLOW_LINKS)).filter(x->x.toString().endsWith(".log")||x.toString().endsWith(".gz")).forEach(x->{try{Path real=x.toRealPath(LinkOption.NOFOLLOW_LINKS);if(!real.startsWith(root))throw new SecurityException("path escape");total[0]+=Files.size(real);if(total[0]>p.getMaxLogArchiveBytes())throw new IOException("archive limit");String e=root.relativize(real).toString().replace('\\','/');if(e.contains(".."))throw new SecurityException("path escape");out.putNextEntry(new ZipEntry(e));Files.copy(real,out);out.closeEntry();}catch(IOException ex){throw new UncheckedIOException(ex);}});}catch(UncheckedIOException e){Files.deleteIfExists(zip);throw e.getCause();}return zip;} }
